const el=id=>document.getElementById(id);let token='',epoch=0,write=false;
async function api(path='',options={}){const r=await fetch('/api/admin/crm/appointments'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function load(){const current=++epoch,d=await api();if(current!==epoch||!token)return;const select=el('editor').elements.opportunity_id;select.replaceChildren();for(const o of d.opportunities){const opt=document.createElement('option');opt.value=o.id;opt.textContent=o.company+' — '+o.title;select.append(opt)}el('rows').replaceChildren();for(const item of d.items){const section=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p'),history=document.createElement('p');h.textContent=item.title;p.textContent=item.company+' — '+item.starts+' → '+item.ends+' — '+item.status;history.textContent=item.history.map(e=>e.status+' ('+e.created_at+' UTC)').join(' · ');section.append(h,p,history);if(write&&item.status==='PLANIFIE'){for(const [status,label] of [['TERMINE','Terminer'],['ANNULE','Annuler']]){const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{b.disabled=true;try{await api('/'+item.id,{method:'PATCH',body:JSON.stringify({status,version:item.version})});await load()}catch(e){el('notice').textContent=e.message;b.disabled=false}};section.append(b)}}el('rows').append(section)}if(!d.items.length)el('rows').textContent='Aucun rendez-vous.'}
el('login-form').onsubmit=async e=>{e.preventDefault();token=el('token').value;el('token').value='';try{const r=await fetch('/api/auth/me',{headers:{Authorization:'Bearer '+token}});write=false;if(r.ok){const me=await r.json();write=(me.permissions.crm??me.permissions['*']??'').includes('W')}else if(token!=='session'){write=true}await load();el('editor').hidden=!write;el('login').hidden=true;el('workspace').hidden=false}catch(e){token='';el('notice').textContent=e.message}};
el('editor').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.starts+='Z';v.ends+='Z';try{await api('',{method:'POST',body:JSON.stringify(v)});e.target.reset();await load();el('notice').textContent='Rendez-vous planifié.'}catch(e){el('notice').textContent=e.message}};
el('logout').onclick=()=>{epoch++;token='';write=false;el('rows').replaceChildren();el('workspace').hidden=true;el('login').hidden=false};
